nnhub"}, {"news_type": "company", "date": "20230724121700", "headline": "Johnson & Johnson, Chevron share gains contribute to Dow's 175-point climb", "summary": "The Dow Jones Industrial Average is trading up Monday morning with shares of Johnson & Johnson and Chevron delivering the strongest returns for the blue-chip...", "source": "MarketWatch"}, {"news_type": "company", "date": "20230724121800", "headline": "Johnson & Johnson Launches Exchange Offer for Separation of Kenvue Inc.", "summary": "NEW BRUNSWICK, N.J., July 24, 2023--Johnson & Johnson (NYSE: JNJ) today announced its intention to split-off at least 80.1% of the shares of Kenvue Inc. (NYSE: KVUE) ("Kenvue") through an exchange offer. Kenvue, formerly Johnson & Johnson’s Consumer Health business, completed its initial public offering ("IPO") in May 2023. Through the planned exchange offer, Johnson & Johnson shareholders can exchange all, some or none of their shares of Johnson & Johnson common stock for shares of Kenvue commo", "source": "Yahoo"}, {"news_type": "company", "date": "20230724122200", "headline": "Kenvue To File Form S-4 Registration Statement in Connection with Johnson & Johnson Exchange Offer Announcement", "summary": "SKILLMAN, N.J., July 24, 2023--Kenvue Inc. (NYSE: KVUE) announced intent to file a Form S-4 Registration Statement today with the Securities and Exchange Commission.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724123409", "headline": "UPDATE 2-J&J starts share exchange offer for consumer health spin-off Kenvue", "summary": "Johnson & Johnson said on Monday it had launched an exchange offer under which its stockholders can opt for shares of Kenvue, its newly listed consumer health unit.  J&J, which currently owns an 89.6% stake in Kenvue, said it intends to split off at least 80.1% of the consumer health company's shares as part of the offering.  The offering will help J&J move a step closer in its plan to spin off the unit and focus on its larger medical devices and pharmaceuticals businesses.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724123811", "headline": "J&J starts share exchange offer for consumer health spin-off Kenvue", "summary": "J&J, which currently owns an 89.6% stake in Kenvue, said it intends to split off at least 80.1% of the consumer health company's shares as part of the offering.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724130500", "headline": "Johnson & Johnson Lost Its Court Battle But Won The Q2 Match", "summary": "Looking for stock market analysis and research with proves results? Zacks.com offers in-depth financial research with over 30years of proven results.", "source": "Benzinga"}, {"news_type": "company", "date": "20230724140300", "headline": "Johnson & Johnson Wants to Swap Kenvue Shares. Expect Details Today.", "summary": "The company plans J&J plans on exchanging up to 1.5 million shares of Kenvue stock that it owns, for outstanding shares of J common stock.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724143415", "headline": "Johnson & Johnson: Resilient, But Clarification On Liability Issue Is Needed", "summary": "Johnson & Johnson has seen solid second quarter results, triggering a modest hike in the full-year guidance. Read more about JNJ stock here.", "source": "SeekingAlpha"}, {"news_type": "company", "date": "20230724145302", "headline": "Raymond James Maintains Johnson & Johnson (JNJ) Outperform Recommendation", "summary": "", "source": "Fintel"}, {"news_type": "company", "date": "20230724163716", "headline": "3 Ultrareliable Dividend Stocks to Buy and Hold for Decades", "summary": "These stocks have decades of annual dividend raises under their belts, and rising healthcare costs mean there could be plenty more to come.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724165845", "headline": "Johnson & Johnson Offers Exchange for Shares of Spinoff Kenvue", "summary": "Johnson & Johnson offers its shareholders the choice to exchange its shares for Kenvue's, the consumer health company it spun off just two months ago.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724170800", "headline": "Johnson & Johnson’s Kenvue Stock Swap Is a Good Deal for Investors", "summary": "The company plans on exchanging up to 1.5 billion shares of Kenvue stock that it owns, for outstanding shares of J&J common stock.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724170824", "headline": "Eli Lilly: Does 'Miracle' Weight Loss Franchise Justify Rising Price Tag?", "summary": "Eli Lilly's share price won't stop climbing on the promise of its miracle diabetes and weight loss drug, tirzepatide. Learn more about LLY stock here.", "source": "SeekingAlpha"}, {"news_type": "company", "date": "20230724174505", "headline": "Are You Looking for a High-Growth Dividend Stock?", "summary": "Dividends are one of the best benefits to being a shareholder, but finding a great dividend stock is no easy task. Does Johnson & Johnson (JNJ) have what it takes? Let's find out.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724181500", "headline": "NEW YORK MARKET CLOSE: Dow extends winning streak ahead of rate call", "summary": "Looking for stock market analysis and research with proves results? Zacks.com offers in-depth financial research with over 30years of proven results.", "source": "Alliance News"}, {"news_type": "company", "date": "20230724184507", "headline": "3 Reasons Why Growth Investors Shouldn't Overlook Johnson & Johnson (JNJ)", "summary": "Johnson & Johnson (JNJ) possesses solid growth attributes, which could help it handily outperform the market.", "source": "Yahoo"}, {"news_type": "company", "date": "20230724184518", "headline": "Russia Is Seizing European Company Assets — What US Businesses Are Still At Risk?", "summary": " ", "source": "Benzinga"}, {"news_type": "company", "date": "20230724191456", "headline": "Psyched: Germany Ships LSD Prodrugs Via DHL, Minneapol